140	function listBookings(state, query) {
141	  const params = new URLSearchParams(query ?? '');
142	  if (!params.has('date')) return { status: 200, body: { bookings: sortBookings(state.bookings) } };
143	  const date = params.get('date');
144	  if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
145	  return { status: 200, body: { bookings: sortBookings(state.bookings.filter((b) => b.date === date)) } };
146	}
147	
148	function checkContentType(header) {
149	  const media = isString(header) ? header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '').toLowerCase() : '';
150	  if (media !== 'application/json') throw new HttpError(415, 'content type must be application/json');
151	}
152	
153	function parseBookingInput(body) {
154	  let data;
155	  try {
156	    data = JSON.parse(body.toString('utf8'));
157	  } catch {
158	    throw new HttpError(400, 'body must be a JSON object');
159	  }
160	  if (!isPlainObject(data)) throw new HttpError(400, 'body must be a JSON object');
161	  const [room, title, date, start, end] = ['room', 'title', 'date', 'start', 'end'].map((k) => ownValue(data, k));
162	  if (!isString(room) || !ROOMS.includes(room)) throw new HttpError(400, 'room must be one of Aurora, Borealis, Cosmos');
163	  if (!isValidTitle(title)) throw new HttpError(400, 'title must be 1 to 80 characters');
164	  if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
165	  if (!isValidTime(start)) throw new HttpError(400, 'start must be HH:MM');
166	  if (!isValidTime(end)) throw new HttpError(400, 'end must be HH:MM');
167	  if (end <= start) throw new HttpError(400, 'end must be after start');
168	  return { room, title: title.trim(), date, start, end };
169	}
170	
171	function createBooking(store, req, body) {
172	  checkContentType(req.headers['content-type']);
173	  if (body.tooLarge) throw new HttpError(413, 'body too large');
174	  const input = parseBookingInput(body.data);
175	  const state = store.state;
176	  const clash = state.bookings.filter((b) => overlaps(b, input))
177	    .reduce((first, b) => (first === null || b.start < first.start ? b : first), null);
178	  if (clash) throw new HttpError(409, `room is already booked from ${clash.start} to ${clash.end}`);
179	  const booking = { id: state.nextId, ...input };
180	  store.commit({ nextId: state.nextId + 1, bookings: [...state.bookings, booking] });
181	  return { status: 201, body: booking };
182	}
183	
184	function deleteBooking(store, id) {
185	  const state = store.state;
186	  const found = /^[1-9][0-9]*$/.test(id) && state.bookings.some((b) => String(b.id) === id);
187	  if (!found) throw new HttpError(404, 'booking not found');
188	  store.commit({ nextId: state.nextId, bookings: state.bookings.filter((b) => String(b.id) !== id) });
189	  return { status: 204, body: null };
190	}
191	
192	// ---------- HTTP plumbing ----------
193	
194	function sendJson(res, status, body) {
195	  if (body === null) {
196	    res.writeHead(status);
197	    res.end();
198	    return;
199	  }
200	  const payload = Buffer.from(JSON.stringify(body), 'utf8');
201	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': payload.length });
202	  res.end(payload);
203	}
204	
205	function sendStatic(res, pathname) {
206	  const file = STATIC_FILES[pathname];
207	  fs.readFile(file.url, (err, data) => {
208	    if (err) {
209	      sendJson(res, 500, { error: 'internal error' });
210	      return;
211	    }
212	    res.writeHead(200, { 'Content-Type': file.type, 'Content-Length': data.length });
213	    res.end(data);
214	  });
215	}
216	
217	// Reads the whole body; keeps at most MAX_BODY bytes and counts every byte received.
218	function readBody(req, onDone) {
219	  const chunks = [];
220	  let received = 0;
221	  req.on('data', (chunk) => {
222	    received += chunk.length;
223	    if (received <= MAX_BODY) chunks.push(chunk);
224	  });
225	  req.on('end', () => onDone({ tooLarge: received > MAX_BODY, data: received > MAX_BODY ? null : Buffer.concat(chunks) }));
226	  req.on('error', () => req.destroy());
227	}
228	
229	function dispatch(store, req, res, body) {
230	  const { path: pathname, query } = splitTarget(req.url);
231	  const { handler, id } = route(req.method, pathname, ROUTES);
232	  switch (handler) {
233	    case 'static': return sendStatic(res, pathname);
234	    case 'listRooms': return sendJson(res, 200, { rooms: [...ROOMS] });
235	    case 'listBookings': return send(res, listBookings(store.state, query));
236	    case 'createBooking': return send(res, createBooking(store, req, body));
237	    case 'deleteBooking': return send(res, deleteBooking(store, id));
238	    default: throw new Error('unknown handler');
239	  }
240	}
241	
242	const send = (res, result) => sendJson(res, result.status, result.body);
243	
244	function handleRequest(store, req, res) {
245	  readBody(req, (body) => {
246	    try {
247	      dispatch(store, req, res, body);
248	    } catch (err) {
249	      const status = err instanceof HttpError ? err.status : 500;
250	      const message = err instanceof HttpError ? err.message : 'internal error';
251	      if (!res.headersSent) sendJson(res, status, { error: message });
252	      else res.destroy();
253	    }
254	  });
255	}
256	
257	/** Holds the in-memory state; commit saves first and only then swaps state. */
258	function createStore(filePath, initial) {
259	  let state = initial;
260	  return {
261	    get state() { return state; },
262	    commit(next) {
263	      saveState(filePath, next);
264	      state = next;
265	    },
266	  };
267	}
268	
269	// ---------- startup ----------
270	
271	function parsePort(raw) {
272	  if (raw === undefined || raw === '') return 3000;
273	  if (!/^[0-9]+$/.test(raw)) return null;
274	  const port = Number(raw);
275	  return port <= 65535 ? port : null;
276	}
277	
278	function main() {
279	  const port = parsePort(process.env.PORT);
280	  if (port === null) {
281	    process.stderr.write(`invalid PORT ${process.env.PORT}\n`);
282	    process.exitCode = 1;
283	    return;
284	  }
285	  const name = process.env.DATA_FILE || 'bookings.json';
286	  const filePath = path.resolve(process.cwd(), name);
287	  const initial = loadState(filePath);
288	  if (initial === null) {
289	    process.stderr.write(`cannot read data file ${name}\n`);
290	    process.exitCode = 1;
291	    return;
292	  }
293	  const store = createStore(filePath, initial);
294	  const server = http.createServer((req, res) => handleRequest(store, req, res));
295	  // Only listen failures (e.g. EADDRINUSE) reach here; request errors are handled per request.
296	  server.once('error', (err) => {
297	    process.stderr.write(`cannot listen on port ${port}: ${err.code ?? 'error'}\n`);
298	    process.exit(1);
299	  });
300	  server.listen(port, '127.0.0.1', () => {
301	    process.stdout.write(`listening on http://127.0.0.1:${server.address().port}\n`);
302	  });
303	}
304	
305	main();
