1	// Room bookings page script. Classic script: runs its setup at once.
2	(function () {
3	  'use strict';
4	
5	  const NO_REPLY = 'Could not reach the server.';
6	  const FALLBACK = 'Request failed.';
7	
8	  const form = document.getElementById('booking-form');
9	  const roomSelect = document.getElementById('room');
10	  const titleInput = document.getElementById('title');
11	  const dateInput = document.getElementById('date');
12	  const startInput = document.getElementById('start');
13	  const endInput = document.getElementById('end');
14	  const bookButton = document.getElementById('book');
15	  const filterInput = document.getElementById('filter-date');
16	  const showAllButton = document.getElementById('show-all');
17	  const list = document.getElementById('booking-list');
18	  const errorBox = document.getElementById('error');
19	
20	  let listGeneration = 0;
21	
22	  // Sends a request. Resolves to { reached: false } when there is no usable
23	  // reply, else { reached: true, status, body }. A 204 body is never read.
24	  async function send(url, options) {
25	    let res;
26	    try {
27	      res = await fetch(url, options);
28	    } catch {
29	      return { reached: false };
30	    }
31	    if (res.status === 204) {
32	      return { reached: true, status: 204, body: null };
33	    }
34	    try {
35	      const body = await res.json();
36	      return { reached: true, status: res.status, body: body };
37	    } catch {
38	      return { reached: false };
39	    }
40	  }
41	
42	  function isObject(value) {
43	    return typeof value === 'object' && value !== null && !Array.isArray(value);
44	  }
45	
46	  function errorMessage(body) {
47	    return isObject(body) && typeof body.error === 'string' ? body.error : FALLBACK;
48	  }
49	
50	  function showError(text) {
51	    errorBox.textContent = text;
52	  }
53	
54	  function showFailure(result) {
55	    showError(result.reached ? errorMessage(result.body) : NO_REPLY);
56	  }
57	
58	  async function loadRooms() {
59	    const result = await send('/api/rooms', { method: 'GET' });
60	    if (!result.reached || result.status !== 200) {
61	      showFailure(result);
62	      return;
63	    }
64	    if (!isObject(result.body) || !Array.isArray(result.body.rooms)) {
65	      showError(FALLBACK);
66	      return;
67	    }
68	    const options = result.body.rooms.map(function (name) {
69	      const option = document.createElement('option');
70	      option.value = name;
71	      option.textContent = name;
72	      return option;
73	    });
74	    roomSelect.replaceChildren(...options);
75	  }
76	
77	  function bookingItem(booking) {
78	    const item = document.createElement('li');
79	    const cancel = document.createElement('button');
80	    cancel.type = 'button';
81	    cancel.textContent = 'Cancel';
82	    cancel.addEventListener('click', function () {
83	      cancelBooking(booking.id, cancel);
84	    });
85	    const text = booking.date + ' ' + booking.start + '-' + booking.end + ' ' +
86	      booking.room + ': ' + booking.title;
87	    item.append(text, cancel);
88	    return item;
89	  }
90	
91	  function emptyItem() {
92	    const item = document.createElement('li');
93	    item.append('No bookings.');
94	    return item;
95	  }
96	
97	  function renderBookings(bookings) {
98	    const items = bookings.length === 0 ? [emptyItem()] : bookings.map(bookingItem);
99	    list.replaceChildren(...items);
100	  }
101	
102	  async function loadList() {
103	    listGeneration += 1;
104	    const generation = listGeneration;
105	    const filter = filterInput.value;
106	    const url = filter === '' ? '/api/bookings' : '/api/bookings?date=' + filter;
107	    const result = await send(url, { method: 'GET' });
108	    if (generation !== listGeneration) {
109	      return;
110	    }
111	    if (!result.reached || result.status !== 200) {
112	      showFailure(result);
113	      return;
114	    }
115	    if (!isObject(result.body) || !Array.isArray(result.body.bookings)) {
116	      showError(FALLBACK);
117	      return;
118	    }
119	    renderBookings(result.body.bookings);
120	  }
121	
122	  async function submitBooking(event) {
123	    event.preventDefault();
124	    if (bookButton.disabled) {
125	      return;
126	    }
127	    bookButton.disabled = true;
128	    const payload = {
129	      room: roomSelect.value,
130	      title: titleInput.value,
131	      date: dateInput.value,
132	      start: startInput.value,
133	      end: endInput.value,
134	    };
135	    const result = await send('/api/bookings', {
136	      method: 'POST',
137	      headers: { 'Content-Type': 'application/json' },
138	      body: JSON.stringify(payload),
139	    });
140	    bookButton.disabled = false;
141	    if (result.reached && result.status === 201) {
142	      titleInput.value = '';
143	      showError('');
144	      loadList();
145	      return;
146	    }
147	    showFailure(result);
148	  }
149	
150	  async function cancelBooking(id, button) {
151	    button.disabled = true;
152	    const result = await send('/api/bookings/' + id, { method: 'DELETE' });
153	    button.disabled = false;
154	    if (!result.reached) {
155	      showError(NO_REPLY);
156	      return;
157	    }
158	    if (result.status === 204) {
159	      showError('');
160	    } else {
161	      showError(errorMessage(result.body));
162	    }
163	    loadList();
164	  }
165	
166	  function showAll() {
167	    filterInput.value = '';
168	    loadList();
169	  }
170	
171	  form.addEventListener('submit', submitBooking);
172	  filterInput.addEventListener('change', loadList);
173	  showAllButton.addEventListener('click', showAll);
174	
175	  loadRooms();
176	  loadList();
177	})();
