    const dir = tmpDir();
    const s = await startServer({ env: { DATA_FILE: path.join(dir, 'nope', 'b.json') } });
    assert.deepEqual((await request(s.port, { path: '/api/bookings' })).json, { bookings: [] });
    assert.equal(fs.existsSync(path.join(dir, 'nope')), false);
